{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.qcom_replen_2_July2025 as WITH sold_yesterday AS ( SELECT sku_group, SUM(TOTAL_QUANTITY) AS units_sold_store, order_date FROM snitch_db.maplemonk.SLIKK_FACT_ITEM WHERE order_date = CURRENT_DATE - 7 GROUP BY sku_group, order_date ), sku_group_data AS ( SELECT sku_group AS sku_group_final, order_date, SUM(TOTAL_QUANTITY) - SUM(RETURN_QUANTITY) AS qty FROM snitch_db.maplemonk.SLIKK_FACT_ITEM GROUP BY sku_group, order_date ), StoreSales AS ( SELECT sku_group_final, SUM(qty) AS total_sales FROM sku_group_data WHERE CURRENT_DATE - order_date <= 60 GROUP BY sku_group_final ), RankedSales AS ( SELECT *, 100 * DIV0(total_sales, SUM(total_sales) OVER ()) AS share FROM StoreSales ), Pareot AS ( SELECT *, SUM(share) OVER (ORDER BY share DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_share FROM RankedSales ), Ratio AS ( SELECT *, CASE WHEN cumulative_share <= 10 THEN \'10%\' WHEN cumulative_share <= 20 THEN \'20%\' WHEN cumulative_share <= 30 THEN \'30%\' WHEN cumulative_share <= 40 THEN \'40%\' WHEN cumulative_share <= 50 THEN \'50%\' WHEN cumulative_share <= 60 THEN \'60%\' WHEN cumulative_share <= 70 THEN \'70%\' WHEN cumulative_share <= 80 THEN \'80%\' WHEN cumulative_share <= 90 THEN \'90%\' ELSE \'100%\' END AS percentage_category FROM Pareot ) , store_replen_interim as ( select qcom_replen_1_July2025.*, (CASE WHEN XS_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL7_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL8_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN NA_UNITS > 1 THEN 1 ELSE 0 END) AS NUM_SIZE_WH_NEW, (CASE WHEN XS_UNITS > 1 AND XS_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS > 1 AND S_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS > 1 AND M_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS > 1 AND L_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS > 1 AND XL_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS > 1 AND XXL_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS > 1 AND XL3_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS > 1 AND XL4_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS > 1 AND XL5_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS > 1 AND XL6_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL7_UNITS > 1 AND XL7_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL8_UNITS > 1 AND XL8_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN NA_UNITS > 1 AND NA_UNITS_STORE>0 THEN 1 ELSE 0 END) AS NUM_SAME_SIZES, NUM_SIZE_WH_NEW + NUM_SIZE_AVAILABLE - NUM_SAME_SIZES as SIZE_AFTER_REPLEN, CASE WHEN replen_1 > 0 AND omc.cumulative_share <= 80 AND SIZE_AFTER_REPLEN>=3 THEN \'REPLEN\' ELSE \'DONT REPLEN\' END AS REPLEN_FLAG, CASE WHEN NUM_SIZE_AVAILABLE < 3 AND omc.cumulative_share>80 THEN \'OUTWARD\' WHEN (omc.cumulative_share <= 80 AND replen_1 =0 ) THEN \'CANNOT REPLEN\' ELSE REPLEN_FLAG END AS Final_action, CASE WHEN REPLEN_FLAG=\'REPLEN\' THEN 1 ELSE 0 END AS FINAL_ALLOC, omc.percentage_category as sku_offline_pareto, from snitch_db.maplemonk.qcom_replen_1_July2025 qcom_replen_1_July2025 LEFT JOIN Ratio omc ON qcom_replen_1_July2025.sku_group = omc.sku_group_final ) select sri.*, sy.order_date as yesterday_order_date, 1 as xs_tsh_low_1, 2 as s_tsh_low_1, 3 as m_tsh_low_1, 3 as l_tsh_low_1, 3 as xl_tsh_low_1, 2 as xxl_tsh_low_1, 2 as xl3_tsh_low_1, 2 as xl4_tsh_low_1, 3 as xl5_tsh_low_1, 3 as xl6_tsh_low_1, 2 as xl7_tsh_low_1, 1 as xl8_tsh_low_1, 2 AS xs_tsh_high, 4 AS s_tsh_high, 6 AS m_tsh_high, 6 AS l_tsh_high, 6 AS xl_tsh_high, 4 AS xxl_tsh_high, 4 AS xl3_tsh_high, 4 AS xl4_tsh_high, 6 AS xl5_tsh_high, 6 AS xl6_tsh_high, 4 AS xl7_tsh_high, 2 AS xl8_tsh_high, ifnull(CAST(LEFT(sku_offline_pareto, LEN(sku_offline_pareto) - 1) AS INT),100) as pareto, CASE WHEN sy.units_sold_store IS NULL THEN 0 ELSE sy.units_sold_store END as units_sold_yesterday, CASE WHEN pareto <= 40 THEN CASE WHEN GREATEST(sri.REPLEN_NOCAP,xs_tsh_high) - XS_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_NOCAP,xs_tsh_high) - XS_UNITS_STORE ELSE 0 END WHEN pareto > 40 and pareto <= 80 THEN CASE WHEN GREATEST(sri.REPLEN_CAP,xs_tsh_low_1) - XS_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_CAP,xs_tsh_low_1) - XS_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'XS\' THEN replen_1 ELSE 0 END END AS XS_alloc, CASE WHEN pareto <= 40 THEN CASE WHEN GREATEST(sri.REPLEN_NOCAP,s_tsh_high) - S_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_NOCAP,s_tsh_high) - S_UNITS_STORE ELSE 0 END WHEN pareto > 40 and pareto <= 80 THEN CASE WHEN GREATEST(sri.REPLEN_CAP,s_tsh_low_1) - S_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_CAP,s_tsh_low_1) - S_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'S\' THEN replen_1 ELSE 0 END END AS S_alloc, CASE WHEN pareto <= 40 THEN CASE WHEN GREATEST(sri.REPLEN_NOCAP,m_tsh_high) - M_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_NOCAP,M_tsh_high) - M_UNITS_STORE ELSE 0 END WHEN pareto > 40 and pareto <= 80 THEN CASE WHEN GREATEST(sri.REPLEN_CAP,M_tsh_low_1) - M_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_CAP,M_tsh_low_1) - M_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'M\' THEN replen_1 ELSE 0 END END AS M_alloc, CASE WHEN pareto <= 40 THEN CASE WHEN GREATEST(sri.REPLEN_NOCAP,l_tsh_high) - L_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_NOCAP,L_tsh_high) - L_UNITS_STORE ELSE 0 END WHEN pareto > 40 and pareto <= 80 THEN CASE WHEN GREATEST(sri.REPLEN_CAP,L_tsh_low_1) - L_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_CAP,L_tsh_low_1) - L_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'L\' THEN replen_1 ELSE 0 END END AS L_alloc, CASE WHEN pareto <= 40 THEN CASE WHEN GREATEST(sri.REPLEN_NOCAP,xl_tsh_high) - XL_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_NOCAP,xl_tsh_high) - XL_UNITS_STORE ELSE 0 END WHEN pareto > 40 and pareto <= 80 THEN CASE WHEN GREATEST(sri.REPLEN_CAP,xl_tsh_low_1) - XL_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_CAP,xl_tsh_low_1) - XL_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'XL\' THEN replen_1 ELSE 0 END END AS XL_alloc, CASE WHEN pareto <= 40 THEN CASE WHEN GREATEST(sri.REPLEN_NOCAP,xxl_tsh_high) - XXL_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_NOCAP,XXL_tsh_high) - XXL_UNITS_STORE ELSE 0 END WHEN pareto > 40 and pareto <= 80 THEN CASE WHEN GREATEST(sri.REPLEN_CAP,xxl_tsh_low_1) - XXL_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_CAP,xxl_tsh_low_1) - XXL_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'XXL\' THEN replen_1 ELSE 0 END END AS XXL_alloc, CASE WHEN pareto <= 40 THEN CASE WHEN GREATEST(sri.REPLEN_NOCAP,xl3_tsh_high) - XL3_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_NOCAP,XL3_tsh_high) - XL3_UNITS_STORE ELSE 0 END WHEN pareto > 40 and pareto <= 80 THEN CASE WHEN GREATEST(sri.REPLEN_CAP,xl3_tsh_low_1) - XL3_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_CAP,xl3_tsh_low_1) - XL3_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'3XL\' THEN replen_1 ELSE 0 END END AS XL3_alloc, CASE WHEN pareto <= 40 THEN CASE WHEN GREATEST(sri.REPLEN_NOCAP,xl4_tsh_high) - XL4_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_NOCAP,XL4_tsh_high) - XL4_UNITS_STORE ELSE 0 END WHEN pareto > 40 and pareto <= 80 THEN CASE WHEN GREATEST(sri.REPLEN_CAP,xl4_tsh_low_1) - XL4_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_CAP,xl4_tsh_low_1) - XL4_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'4XL\' THEN replen_1 ELSE 0 END END AS XL4_alloc, CASE WHEN pareto <= 40 THEN CASE WHEN GREATEST(sri.REPLEN_NOCAP,xl5_tsh_high) - XL5_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_NOCAP,XL5_tsh_high) - XL5_UNITS_STORE ELSE 0 END WHEN pareto > 40 and pareto <= 80 THEN CASE WHEN GREATEST(sri.REPLEN_CAP,xl5_tsh_low_1) - XL5_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_CAP,xl5_tsh_low_1) - XL5_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'5XL\' THEN replen_1 ELSE 0 END END AS XL5_alloc, CASE WHEN pareto <= 40 THEN CASE WHEN GREATEST(sri.REPLEN_NOCAP,xl6_tsh_high) - XL6_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_NOCAP,XL6_tsh_high) - XL6_UNITS_STORE ELSE 0 END WHEN pareto > 40 and pareto <= 80 THEN CASE WHEN GREATEST(sri.REPLEN_CAP,xl6_tsh_low_1) - XL6_UNITS_STORE > 0 THEN GREATEST(sri.REPLEN_CAP,xl6_tsh_low_1) - XL6_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'6XL\' THEN replen_1 ELSE 0 END END AS XL6_alloc, CASE WHEN size_mapped = \'NA\' THEN GREATEST(sri.REPLEN_NOCAP,replen_1) ELSE 0 END AS NA_alloc FROM store_replen_interim sri LEFT JOIN sold_yesterday sy ON sri.sku_group=sy.sku_group ;",
